import{_ as t,c as o,o as s,a3 as d}from"./chunks/framework.BNw1pucY.js";const u=JSON.parse('{"title":"Fix common agent problems","description":"Match the symptom to one corrective action, then inspect the session trace when the first fix is not enough.","frontmatter":{"title":"Fix common agent problems","description":"Match the symptom to one corrective action, then inspect the session trace when the first fix is not enough."},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),a={name:"troubleshooting.md"};function r(i,e,n,h,c,l){return s(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="fix-common-agent-problems" tabindex="-1">Fix common agent problems <a class="header-anchor" href="#fix-common-agent-problems" aria-label="Permalink to &quot;Fix common agent problems&quot;">​</a></h1><p>Start with three checks:</p><ol><li>Run <code>agent-sdk validate --dir .</code>.</li><li>Confirm the expected agent and connections in <code>agent-sdk info --dir . --json</code>.</li><li>Reproduce the problem once, then read the serve log or the <a href="#read-the-session-trace">session trace</a>.</li></ol><h2 id="serve-or-the-playground-won-t-work" tabindex="-1">Serve or the playground won&#39;t work <a class="header-anchor" href="#serve-or-the-playground-won-t-work" aria-label="Permalink to &quot;Serve or the playground won&#39;t work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td>The playground is blank or lists no agents</td><td>Start <code>agent-sdk serve</code>, because the playground gets its agents from the server.</td></tr><tr><td>Agent-file edits don&#39;t appear</td><td>Open the URL that <code>serve --dev</code> prints, and press Enter in its terminal to reload.</td></tr><tr><td>Sessions exist but the list is empty</td><td>The list shows only your own sessions, so use the identity that created them.</td></tr></tbody></table><h2 id="a-turn-fails-or-misbehaves" tabindex="-1">A turn fails or misbehaves <a class="header-anchor" href="#a-turn-fails-or-misbehaves" aria-label="Permalink to &quot;A turn fails or misbehaves&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td>Reads and greps keep failing with <code>NGHTTP2_FRAME_SIZE_ERROR</code></td><td>Run the agent under Node 22.13 or newer, never Bun.</td></tr><tr><td><code>Semantic search has been removed. Use Grep.</code></td><td>Delete <code>search</code> from a custom <code>fs</code>, drop <code>SearchQuery</code> and <code>SearchResult</code>, and remove <code>SemanticSearch</code> or <code>semSearch</code> from <code>tools</code> and <code>bot/tools/</code>.</td></tr><tr><td>The turn reports a missing API key</td><td>Set <code>CURSOR_API_KEY</code>, <code>CURSOR_API_KEY_FILE</code>, or <code>CURSOR_SERVICE_ACCOUNT_KEY</code>, or run <code>agent-sdk login</code>.</td></tr><tr><td>Login works but the model host rejects the key</td><td>Point <code>CURSOR_API_BASE_URL</code> and <code>CURSOR_BACKEND_URL</code> at the same API host.</td></tr><tr><td>The first turn reports <code>[resource_exhausted]</code></td><td>The model is usually out of capacity. If a GitHub event started the turn, check for a GitHub <code>429</code> rate-limit response first.</td></tr><tr><td>Replies quote an ancestor <code>AGENTS.md</code> or unrelated repository rules</td><td>Set <code>defineAgent({ local: { cwd } })</code> so the agent doesn&#39;t inherit the parent checkout. <code>/v1/info</code> shows the current <code>local.cwd</code>.</td></tr><tr><td>The model lists IDE meta-tools but never calls named MCP tools</td><td>Set <code>advertiseTools: true</code> on the local connection.</td></tr><tr><td>Server tools, skills, or seed files are missing</td><td>Check the discovered project in <code>/v1/info</code>, and follow the warning from <code>validate</code>.</td></tr><tr><td><code>validate</code> and <code>run</code> pass but CI type-checking fails</td><td>Return JSON-shaped tool results, such as object literals or <code>type</code> aliases, instead of <code>interface</code> types.</td></tr></tbody></table><h2 id="http-returns-401-403-or-409" tabindex="-1">HTTP returns 401, 403, or 409 <a class="header-anchor" href="#http-returns-401-403-or-409" aria-label="Permalink to &quot;HTTP returns 401, 403, or 409&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td><code>401</code> outside local development</td><td>Send the bearer token, alias token, or channel credential. Default custom routes accept only direct loopback calls.</td></tr><tr><td><code>403</code> on a stream or follow-up</td><td>Use the identity that created the session.</td></tr><tr><td>A custom route fails through a tunnel or LAN</td><td>Protect the host with <code>--bearer-token</code> or channel auth. Use <code>--allow-anonymous</code> only behind a proxy that authenticates every caller.</td></tr><tr><td><code>409</code> on a follow-up</td><td>Refresh the rotating <code>continuationToken</code>. Task sessions don&#39;t accept follow-ups.</td></tr><tr><td><code>409 session_busy</code> from <code>call --session</code></td><td>Wait for the turn, omit <code>--session</code>, or mark a read-only tool <code>effect: &quot;read&quot;</code> so it can run alongside the turn.</td></tr></tbody></table><h2 id="a-hosted-deployment-fails-or-looks-stale" tabindex="-1">A hosted deployment fails or looks stale <a class="header-anchor" href="#a-hosted-deployment-fails-or-looks-stale" aria-label="Permalink to &quot;A hosted deployment fails or looks stale&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td><code>validate</code> or <code>deploy</code> reports <code>architecture &quot;v2&quot; requires a named secret</code></td><td>Replace the literal or getter with a <a href="./deployment.html#add-egress-and-secrets">named secret</a>, and set its value with <code>agent-sdk secret set &lt;slug&gt; NAME</code>.</td></tr><tr><td>Local changes don&#39;t appear after deploy</td><td><code>deploy</code> builds the pushed ref, so commit and push your changes, then deploy again.</td></tr><tr><td>The deployment never reaches <code>running</code></td><td>Run <code>agent-sdk deployment get &lt;slug&gt;</code>, and fix the error it reports.</td></tr><tr><td>A secret or egress change has no effect</td><td>Confirm the name with <code>secret list</code>, check that the <code>hosting</code> block is on the pushed ref, and redeploy.</td></tr><tr><td>A hosted schedule doesn&#39;t fire</td><td>Check that the deployment is running and that the schedule is in <code>bot/schedules/</code> on the deployed ref.</td></tr><tr><td>A custom route returns <code>429</code></td><td>Wait for the time in <code>Retry-After</code>, then send it again.</td></tr></tbody></table><h2 id="github-deliveries-fail" tabindex="-1">GitHub deliveries fail <a class="header-anchor" href="#github-deliveries-fail" aria-label="Permalink to &quot;GitHub deliveries fail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td><code>github forward</code> gets <code>401</code> on every delivery</td><td>Clear the token variables so the forwarder uses your <code>gh</code> login, as in <code>GITHUB_TOKEN= GH_TOKEN= agent-sdk github forward</code>.</td></tr><tr><td><code>Hook already exists</code></td><td>Stop the stale forwarder. GitHub allows one per repository.</td></tr><tr><td>Direct webhooks are rejected outside <code>--dev</code></td><td>Set the same <code>GITHUB_WEBHOOK_SECRET</code> on the signer and the server.</td></tr><tr><td>You can&#39;t create a forwarder</td><td>Use <code>agent-sdk github replay &lt;pr-url&gt;</code>, which needs only pull access.</td></tr></tbody></table><h2 id="slack-doesn-t-respond" tabindex="-1">Slack doesn&#39;t respond <a class="header-anchor" href="#slack-doesn-t-respond" aria-label="Permalink to &quot;Slack doesn&#39;t respond&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td>Logs say <code>channel idle ... missing credentials</code></td><td>Run <code>agent-sdk slack create --dir &lt;agent&gt;</code>, then check the prefix with <code>agent-sdk slack doctor</code>.</td></tr><tr><td><code>slack create</code> waits for workspace approval</td><td>Keep the CLI running and open the <strong>Request approval</strong> link it prints. After an admin approves, select <strong>Retry</strong> in the <a href="https://cursor.com/dashboard/deployed-agents" target="_blank" rel="noreferrer">Deployed Agents</a> <strong>Add Slack</strong> wizard.</td></tr><tr><td>The bot ignores ordinary channel posts</td><td>Configure <code>engagement.channelPosts</code>, create the app with <code>--channel-posts</code>, and invite it to each allowed channel.</td></tr></tbody></table><h2 id="mcp-authorization-fails" tabindex="-1">MCP authorization fails <a class="header-anchor" href="#mcp-authorization-fails" aria-label="Permalink to &quot;MCP authorization fails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td><code>must be defineConnection({ url, oauth: true })</code></td><td>Add <code>oauth: true</code> to the connection, or fix the filename you passed to <code>mcp oauth</code>.</td></tr><tr><td>Local auth works but hosted calls return unauthorized</td><td>Your local OAuth tokens don&#39;t reach a deployment. Use a <code>cursorAccount: true</code> connection, as described in <a href="./guides/mcp-oauth.html#use-an-oauth-server-from-a-hosted-agent">Host MCP OAuth</a>.</td></tr><tr><td>The model invents <code>mcp_auth</code> instead of calling the server</td><td>Set <code>advertiseTools: true</code> for named local tools, or expose a wrapper through <code>ctx.host.mcp</code>.</td></tr></tbody></table><h2 id="schedules-or-reminders-stall" tabindex="-1">Schedules or reminders stall <a class="header-anchor" href="#schedules-or-reminders-stall" aria-label="Permalink to &quot;Schedules or reminders stall&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td>A schedule or reminder never fires under <code>--dev</code></td><td><code>--dev</code> doesn&#39;t fire them on its own, so trigger one through its <code>/v1/dev/schedules/&lt;id&gt;</code> or <code>/v1/dev/reminders/&lt;id&gt;</code> route.</td></tr><tr><td>A reminder is disarmed with <code>handler_lost_on_restart</code></td><td>Recreate handler-form reminders after a restart, or use a prompt-form reminder.</td></tr><tr><td>One schedule fires on several self-hosted processes</td><td>Pass <code>--no-schedules</code> to every serving process but one.</td></tr></tbody></table><h2 id="read-the-session-trace" tabindex="-1">Read the session trace <a class="header-anchor" href="#read-the-session-trace" aria-label="Permalink to &quot;Read the session trace&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slug</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sessionI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slug</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">trace-pat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Find a hosted session with <code>session list</code>, then print its events with <code>--view events</code>. For a local run, pass the trace path from <code>agent-sdk run</code> to <code>--file</code>. Pair each <code>actions.requested</code> event with its <code>action.result</code> to find the call that failed.</p>`,22)])])}const k=t(a,[["render",r]]);export{u as __pageData,k as default};
